#include <iostream>
#include <string>
#include <vector>
using namespace std;

// pi[i] = length of the longest proper prefix of s[0..i] that is also its suffix.
vector<int> prefixFunction(const string& s) {
    int n = (int)s.size();
    vector<int> pi(n, 0);
    for (int i = 1; i < n; ++i) {
        int k = pi[i - 1];                            // the border we try to extend
        while (k > 0 && s[i] != s[k]) k = pi[k - 1];  // fall back to the next shorter border
        if (s[i] == s[k]) ++k;
        pi[i] = k;
    }
    return pi;
}

// Start of every occurrence of pattern in text, in O(|pattern| + |text|).
vector<int> findAll(const string& pattern, const string& text) {
    string s = pattern + '\0' + text;  // a separator that occurs in neither string
    vector<int> pi = prefixFunction(s);
    vector<int> hits;
    int m = (int)pattern.size();
    for (int i = m + 1; i < (int)s.size(); ++i)
        if (pi[i] == m) hits.push_back(i - 2 * m);
    return hits;
}

int main() {
    string s = "abacabab";
    cout << "s  = " << s << "\npi =";
    for (int v : prefixFunction(s)) cout << ' ' << v;
    cout << "\n";

    string pattern = "ababc", text = "abababcabababcab";
    cout << pattern << " occurs in " << text << " at:";
    for (int i : findAll(pattern, text)) cout << ' ' << i;
    cout << "\n";

    // The shortest period of r is n - pi[n-1] when that length divides n.
    string r = "abcabcabcabc";
    int p = (int)r.size() - prefixFunction(r).back();
    cout << r << " is " << r.substr(0, p) << " repeated " << (int)r.size() / p << " times\n";
    return 0;
}

#include <algorithm>
#include <iostream>
#include <string>
#include <vector>
using namespace std;

// z[i] = length of the longest common prefix of s and s[i..]; z[0] stays 0.
vector<int> zFunction(const string& s) {
    int n = (int)s.size();
    vector<int> z(n, 0);
    int l = 0, r = 0;  // [l, r) is the match window that reaches furthest right
    for (int i = 1; i < n; ++i) {
        if (i < r) z[i] = min(r - i, z[i - l]);  // reuse what the window already tells us
        while (i + z[i] < n && s[z[i]] == s[i + z[i]]) ++z[i];
        if (i + z[i] > r) {
            l = i;
            r = i + z[i];
        }
    }
    return z;
}

int main() {
    string s = "aabcaabxaaz";
    cout << "s = " << s << "\nz =";
    for (int v : zFunction(s)) cout << ' ' << v;
    cout << "\n";

    string pattern = "aab", text = "baabaaabaab";
    string joined = pattern + '$' + text;  // '$' occurs in neither string
    vector<int> z = zFunction(joined);
    int m = (int)pattern.size();
    cout << pattern << " occurs in " << text << " at:";
    for (int i = m + 1; i < (int)joined.size(); ++i)
        if (z[i] >= m) cout << ' ' << i - m - 1;
    cout << "\n";
    return 0;
}
